// Deals (#809): time-limited DISCOUNTS on paid AI products. They ride in the
// `deals` section of offers.json (generated by scripts/load-deals.mjs), apart
// from `offers`, so no free-offer count, listing, search, feed or offer page
// ever includes one. The build already dropped expired deals (ADR 0001): this
// module never filters on the visitor's clock.

import type { Deal, OffersIndex } from "../types/offers-index";

export type { Deal };
export type DealOccasion = Deal["occasion"];
export type DealCategory = Deal["category"];

export const OCCASIONS: DealOccasion[] = [
  "black_friday",
  "cyber_monday",
  "christmas_new_year",
  "other",
];

export const OCCASION_LABELS: Record<DealOccasion, string> = {
  black_friday: "Black Friday",
  cyber_monday: "Cyber Monday",
  christmas_new_year: "Christmas & New Year",
  other: "Other sale",
};

export const DEAL_CATEGORY_LABELS: Record<DealCategory, string> = {
  ai_subscription: "AI subscription",
  coding_agent: "Coding agent / IDE",
  ai_tool_api: "AI tool / API",
  agent_compute: "Compute for agents",
};

/** The plain-words reminder every deal surface carries. */
export const NOT_FREE_NOTE =
  "Deals are discounts on paid plans: you still pay. They are not free credits and are not counted as free offers.";

/** Shared by deals.html's meta description and its JSON-LD (prerender.mjs). */
export const DEALS_DESCRIPTION =
  "Seasonal discounts on AI subscriptions, coding agents, AI tools and compute, checked on each vendor's own page. Deals are paid discounts, not free credits.";

/** Running deals from the build (empty when the index has none). */
export function dealsOf(index: OffersIndex): Deal[] {
  return index.deals ?? [];
}

/** Deals for one occasion filter value ("" = all). */
export function filterDeals(deals: Deal[], occasion: string): Deal[] {
  return occasion ? deals.filter((d) => d.occasion === occasion) : deals;
}

/** Occasions present in `deals`, in OCCASIONS order. */
export function occasionsIn(deals: Deal[]): DealOccasion[] {
  return OCCASIONS.filter((o) => deals.some((d) => d.occasion === o));
}

/** Parse ?occasion= into a known occasion, else "" (all). */
export function occasionFromSearch(search: string): DealOccasion | "" {
  const value = new URLSearchParams(search).get("occasion") ?? "";
  return (OCCASIONS as string[]).includes(value) ? (value as DealOccasion) : "";
}

/** Relative href of a deal's own page, from a root-level document. */
export function dealHref(slug: string): string {
  return `deals/${slug}.html`;
}

/** Host of the vendor page, for the outbound button label. */
export function dealHost(url: string): string {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return url;
  }
}

/**
 * A deal page's meta description, shared by prerender.mjs and the JSON-LD so
 * the two never diverge. Always says "deal", never "free".
 */
export function dealMetaDescription(deal: Deal): string {
  const text = `Deal (not free): ${deal.discount} on ${deal.provider} — ends ${deal.expiry_date}.`;
  return text.length > 160 ? text.slice(0, 157).trimEnd() + "..." : text;
}
